    // 3. On `/basket`, apply voucher SAVE10.
    await page.goto("/basket");
    await applyVoucher(page, "SAVE10");

    await expectTotals(page, {
      subtotal: "$27.78",
      offers: "$0.00",
      voucher: "-$2.78",
      delivery: "$2.99",
      total: "$27.99",
    });
  });

  test("SAVE10 takes 10% off lines without a multi-buy offer", async ({ page, request }) => {
